<?php
require_once __DIR__.'/bootstrap.php';$uid=require_login();$user=current_user($pdo);$error='';
if($_SERVER['REQUEST_METHOD']==='POST') {check_csrf();$name=trim((string)($_POST['display_name']??''));$bio=trim((string)($_POST['bio']??''));if(mb_strlen($name)<1 || mb_strlen($name)>80 || mb_strlen($bio)>255) $error='Name must be 1–80 characters and bio up to 255.';else{$q=$pdo->prepare('UPDATE users SET display_name=?,bio=? WHERE id=?');$q->execute([$name,$bio,$uid]);flash('Profile updated.');go('profile.php');}}
page_top('Edit profile',$user);?><div class="heading"><a href="profile.php">←</a><strong>Edit profile</strong></div><div class="settings"><h2>Your profile</h2><?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?><form method="post" class="auth-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Display name<input name="display_name" maxlength="80" required value="<?=e($_POST['display_name']??$user['display_name'])?>"></label><label>Bio<textarea name="bio" maxlength="255" rows="4"><?=e($_POST['bio']??$user['bio'])?></textarea></label><button class="primary">Save changes</button></form></div><?php page_bottom(); ?>
